//! The service owns one wallet account which holds the chain's native asset, and sends that asset
//! to any account which asks for it.

// Required by code generated by the upstream `#[instrument]` macro.
extern crate miden_node_tracing as tracing;

use std::path::PathBuf;
use std::time::Duration;

use anyhow::Context;
use miden_node_proto::server::funding_service_api;
use miden_node_tracing::info;
use miden_node_utils::genesis::GenesisBlock;
use miden_node_utils::shutdown::CancellationToken;
use miden_node_utils::tasks::Tasks;
use miden_protocol::account::AccountId;
use miden_protocol::asset::FungibleAsset;
use tokio::net::TcpListener;
use url::Url;

use crate::account::FunderKey;
use crate::node::RpcNodeClient;
use crate::server::FundingRpcServer;
use crate::status::{StatusRefresher, StatusSnapshot};

mod account;
mod node;
mod server;
mod status;

// CONSTANTS
// =================================================================================================

const COMPONENT: &str = "miden-funding-service";

/// Tracing target used for user-visible events.
pub const LOG_TARGET: &str = "user::miden-funding-service";

/// Default largest amount one request may ask for, in base units of the native asset.
pub const DEFAULT_MAX_AMOUNT: u64 = 1_000_000_000;

/// Default timeout of a request to the node's RPC API.
pub const DEFAULT_RPC_TIMEOUT: Duration = Duration::from_secs(10);

/// Default timeout of a gRPC request served by this service.
pub const DEFAULT_GRPC_TIMEOUT: Duration = Duration::from_secs(300);

/// How often the service reads the funding account from the node.
const STATUS_REFRESH_INTERVAL: Duration = Duration::from_secs(30);

// CONFIGURATION
// =================================================================================================

/// The configuration of the funding service.
pub struct FundingServiceConfig {
    rpc_url: Url,
    account_file: PathBuf,
    genesis: GenesisBlock,
    grpc_timeout: Duration,
    rpc_timeout: Duration,
    max_amount: u64,
}

impl FundingServiceConfig {
    /// Creates a configuration with default timeouts and limits.
    ///
    /// The genesis block names the fee asset. The node's RPC API does not serve the protocol
    /// configuration, so the operator must supply the genesis block from a trusted source.
    pub fn new(rpc_url: Url, account_file: PathBuf, genesis: GenesisBlock) -> Self {
        Self {
            rpc_url,
            account_file,
            genesis,
            grpc_timeout: DEFAULT_GRPC_TIMEOUT,
            rpc_timeout: DEFAULT_RPC_TIMEOUT,
            max_amount: DEFAULT_MAX_AMOUNT,
        }
    }

    #[must_use]
    pub fn with_grpc_timeout(mut self, timeout: Duration) -> Self {
        self.grpc_timeout = timeout;
        self
    }

    #[must_use]
    pub fn with_rpc_timeout(mut self, timeout: Duration) -> Self {
        self.rpc_timeout = timeout;
        self
    }

    #[must_use]
    pub fn with_max_amount(mut self, max_amount: u64) -> Self {
        self.max_amount = max_amount;
        self
    }

    /// Connects to the node and builds the service.
    pub async fn build(self) -> anyhow::Result<FundingService> {
        let funder_key = FunderKey::load(&self.account_file)
            .context("failed to load the funding account file")?;

        let node = RpcNodeClient::connect(&self.rpc_url, self.rpc_timeout)
            .await
            .context("failed to connect to the node RPC API")?;

        // A genesis block from another chain would name the wrong fee asset, so the service must
        // not start when the node serves a different chain.
        let node_genesis = node.genesis_header().commitment();
        let configured_genesis = self.genesis.inner().header().commitment();
        anyhow::ensure!(
            configured_genesis == node_genesis,
            "the genesis block does not match the node: the genesis block commits to \
             {configured_genesis}, the node to {node_genesis}",
        );

        // The fee asset is constant for the chain and is only named by the protocol configuration,
        // which the node's RPC API does not serve. The remaining fee parameters are in every block
        // header, and the status refresher reads them at the block it reports.
        let fee_faucet_id = self.genesis.protocol_config().fee_asset_id().faucet_id();
        let fee_parameters = node.genesis_header().fee_parameters().clone();

        // A note holds the amount as a fungible asset, so an amount the asset type cannot express
        // must fail at startup instead of on every request.
        FungibleAsset::new(fee_faucet_id, self.max_amount)
            .context("--max-amount is not a valid amount of the native asset")?;

        info!(
            target: LOG_TARGET,
            "Funding service initialized",
            account.id = funder_key.account_id(),
            asset.faucet_id = fee_faucet_id,
            fee.verification_base_fee = fee_parameters.verification_base_fee(),
            funding_service.max_amount = self.max_amount
        );

        Ok(FundingService {
            node,
            funder_key,
            fee_faucet_id,
            max_amount: self.max_amount,
            grpc_timeout: self.grpc_timeout,
        })
    }
}

// FUNDING SERVICE
// =================================================================================================

/// The funding service, ready to run.
pub struct FundingService {
    node: RpcNodeClient,
    funder_key: FunderKey,
    fee_faucet_id: AccountId,
    max_amount: u64,
    grpc_timeout: Duration,
}

impl FundingService {
    /// Runs the gRPC server and the status refresher until one of them stops.
    pub async fn run(
        self,
        listener: TcpListener,
        shutdown: CancellationToken,
    ) -> anyhow::Result<()> {
        let (health_reporter, health_service) = tonic_health::server::health_reporter();
        health_reporter
            .set_service_status(
                funding_service_api::service_name(),
                tonic_health::ServingStatus::Serving,
            )
            .await;

        let status = StatusSnapshot::new(self.funder_key.account_id(), self.max_amount);

        let mut tasks = Tasks::new();

        let server = FundingRpcServer::new(status.clone(), self.grpc_timeout);
        let server_shutdown = shutdown.clone();
        tasks.spawn("grpc-server", async move {
            server
                .serve(listener, health_service, server_shutdown)
                .await
                .context("the funding service gRPC server failed")
        });

        let refresher = StatusRefresher::new(
            self.node,
            self.funder_key.account_id(),
            self.fee_faucet_id,
            status,
            STATUS_REFRESH_INTERVAL,
        );
        let refresher_shutdown = shutdown.clone();
        tasks.spawn("status-refresher", async move {
            refresher
                .run(refresher_shutdown)
                .await
                .context("the funding service status refresher failed")
        });

        tasks
            .join_next_or_cancelled(shutdown)
            .await
            .context("a funding service task failed")
    }
}
